-- Datos migrados a PostgreSQL (tablas: restaurant, scores, users)

CREATE TABLE "restaurant" (
    "restaurantID" INTEGER NOT NULL,
    "name" VARCHAR(40) NOT NULL,
    "province" VARCHAR(50) NOT NULL,
    "address" VARCHAR(100) NOT NULL,
    "ZIP" INTEGER,
    "url" VARCHAR(100),
    "phone" BIGINT,
    "foodType" VARCHAR(40),
    "userID" INTEGER NOT NULL,
    "latitude" VARCHAR(12),
    "longitude" VARCHAR(12),
    "apiID" VARCHAR(100),
    CONSTRAINT "pk_restaurant" PRIMARY KEY ("restaurantID"),
    CONSTRAINT "fk_restaurant_user" FOREIGN KEY ("userID") REFERENCES "users" ("id")
);

CREATE TABLE "scores" (
    "scoreID" INTEGER NOT NULL,
    "comment" VARCHAR(300),
    "created" DATE,
    "generalScore" SMALLINT NOT NULL,
    "allergenChart" SMALLINT NOT NULL,
    "fidelityScore" SMALLINT NOT NULL,
    "attentionScore" SMALLINT NOT NULL,
    "userID" INTEGER NOT NULL,
    "restaurantID" INTEGER NOT NULL,
    "userName" VARCHAR(50) NOT NULL,
    "allergicReaction" SMALLINT,
    CONSTRAINT "pk_scores" PRIMARY KEY ("scoreID"),
    CONSTRAINT "fk_scores_user" FOREIGN KEY ("userID") REFERENCES "users" ("id"),
    CONSTRAINT "fk_scores_restaurant" FOREIGN KEY ("restaurantID") REFERENCES "restaurant" ("restaurantID")
);


